import{_ as e,a as s,c as t,b as o}from"./chunks/framework.b9WMfGr4.js";const g=JSON.parse('{"title":"04-GitHub个人令牌生成","description":"","frontmatter":{"title":"04-GitHub个人令牌生成","create-time":"2026-05-16T00:00:00.000Z","update-time":"2026-05-16T00:00:00.000Z"},"headers":[],"relativePath":"posts/开发经验/Git与版本控制/04-GitHub个人令牌生成.md","filePath":"posts/开发经验/Git与版本控制/04-GitHub个人令牌生成.md"}'),n={name:"posts/开发经验/Git与版本控制/04-GitHub个人令牌生成.md"};function a(l,i,r,p,d,c){return s(),t("div",null,[...i[0]||(i[0]=[o('<h2 id="github-加入团队项目开发时身份验证" tabindex="-1">Github 加入团队项目开发时身份验证 <a class="header-anchor" href="#github-加入团队项目开发时身份验证" aria-label="Permalink to &quot;Github 加入团队项目开发时身份验证&quot;">​</a></h2><p>问题描述：</p><p>我加入了一个 Github 团队，需要拉取项目，但是 Github 要求我登陆身份验证，我输入了用户名，以及 Github 的登陆密码之后，还是提示失败。</p><p>你遇到的核心问题是：<strong>GitHub 早已禁用了账号密码直接认证 Git 操作</strong>，HTTPS 方式克隆/推送代码时，<strong>密码栏必须填写「个人访问令牌（PAT）」</strong>，而不是你的 GitHub 登录密码。</p><p>我一步步教你解决，超简单：</p><hr><h3 id="第一步-生成-github-个人访问令牌-pat" tabindex="-1">第一步：生成 GitHub 个人访问令牌（PAT） <a class="header-anchor" href="#第一步-生成-github-个人访问令牌-pat" aria-label="Permalink to &quot;第一步：生成 GitHub 个人访问令牌（PAT）&quot;">​</a></h3><ol><li>浏览器登录你的 GitHub 账号</li><li>点击右上角头像 → <strong>Settings（设置）</strong></li><li>左侧菜单栏拉到最底 → <strong>Developer settings（开发者设置）</strong></li><li>左侧选择 <strong>Personal access tokens（个人访问令牌）</strong> → <strong>Tokens (classic)</strong></li><li>点击 <strong>Generate new token</strong> → <strong>Generate new token (classic)</strong></li><li>按提示填写： <ul><li><strong>Note</strong>：给令牌起个名字（比如 <code>git-clone</code>）</li><li><strong>Expiration</strong>：过期时间（建议选 <code>No expiration</code> 永久有效）</li><li><strong>Select scopes</strong>：<strong>只勾选 <code>repo</code></strong>（仓库权限，必须）</li></ul></li><li>拉到最底点击 <strong>Generate token</strong></li><li><strong>关键</strong>：生成的令牌以 <code>ghp_</code> 开头，<strong>只显示这一次，立刻复制保存</strong>！</li></ol><hr><h3 id="第二步-重新克隆仓库" tabindex="-1">第二步：重新克隆仓库 <a class="header-anchor" href="#第二步-重新克隆仓库" aria-label="Permalink to &quot;第二步：重新克隆仓库&quot;">​</a></h3><p>回到你的终端，重新执行克隆命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> https://github.com/adachissss/ourdb.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ol><li>提示 <code>Username</code>：输入你的 GitHub 用户名 <code>Kualk4410</code></li><li>提示 <code>Password</code>：<strong>粘贴你刚才复制的 PAT 令牌</strong>（粘贴时终端不会显示字符，直接回车即可）</li></ol><p>✅ 就能成功克隆了！</p><hr><h3 id="第三步-可选-永久保存凭证-不用每次输入" tabindex="-1">第三步（可选）：永久保存凭证，不用每次输入 <a class="header-anchor" href="#第三步-可选-永久保存凭证-不用每次输入" aria-label="Permalink to &quot;第三步（可选）：永久保存凭证，不用每次输入&quot;">​</a></h3><p>WSL/Linux 下执行这条命令，让 Git 记住你的令牌，后续操作不用重复输：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#D19A66;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> credential.helper</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> store</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><hr><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><ol><li>错误原因：GitHub 不支持密码登录，必须用 <strong>PAT 令牌</strong>；</li><li>操作核心：密码栏粘贴生成的 <code>ghp_</code> 开头令牌；</li><li>优化：配置凭证存储，一劳永逸。</li></ol>',21)])])}const u=e(n,[["render",a]]);export{g as __pageData,u as default};
